// Single classification dictionary for every metric this app surfaces --
// tier is one of 'sourced' | 'calculated' | 'heuristic':
//   sourced    -- a reported figure read directly off a real source (Screener.in,
//                 Yahoo Finance) or entered directly by the user, not derived.
//   calculated -- a deterministic formula (named or arithmetic) applied to
//                 sourced figures. No subjective inputs, but may rely on a
//                 disclosed simplifying assumption (see `methodology`).
//   heuristic  -- a disclosed, in-house analytical judgment: a scoring
//                 formula this project defined, a fixed assumption constant
//                 (e.g. a risk-free rate), or a qualitative classification.
//                 Never presented as analyst consensus or a named external
//                 model unless it actually is one.
// confidence is independent of tier -- a 'calculated' figure can still be
// Low confidence (e.g. built on a short history window).
//
// Attached once per research payload as `data.metricMeta` (see
// data/watchlist/research.mjs) -- the frontend's infoIcon() helper
// (script.js) is the only place this is rendered, so there is one source of
// truth instead of duplicated classification strings per tab.
const registry = {
  price: { tier: 'sourced', confidence: 'High', label: 'Current market price', methodology: 'Latest close from Yahoo Finance’s public chart endpoint.' },
  pe: { tier: 'sourced', confidence: 'High', label: 'P/E', methodology: 'Reported trailing P/E (Screener.in for India; Yahoo does not expose this for other markets).' },
  pb: { tier: 'calculated', confidence: 'High', label: 'P/B', methodology: 'Price ÷ reported book value per share.' },
  roe: { tier: 'sourced', confidence: 'High', label: 'ROE', methodology: 'Reported return on equity (Screener.in, India only).' },
  roce: { tier: 'sourced', confidence: 'High', label: 'ROCE', methodology: 'Reported return on capital employed (Screener.in, India only).' },
  dividendYield: { tier: 'sourced', confidence: 'High', label: 'Dividend yield', methodology: 'Reported trailing dividend yield.' },
  rsi14: { tier: 'calculated', confidence: 'High', label: 'RSI (14)', methodology: 'Wilder’s 14-period RSI over the trailing 1y daily close series.' },
  macd: { tier: 'calculated', confidence: 'High', label: 'MACD', methodology: 'Standard 12/26/9 EMA MACD over the trailing 1y daily close series.' },
  movingAverages: { tier: 'calculated', confidence: 'High', label: '20/50/100/200 DMA', methodology: 'Simple moving average of daily closes; a period renders N/A until enough trading days exist.' },
  avgVolume20: { tier: 'calculated', confidence: 'High', label: 'Average volume (20D)', methodology: 'Simple average of the trailing 20 daily trading volumes, from the same daily OHLCV series every other technical indicator already uses.' },
  compositeScore: { tier: 'heuristic', confidence: 'Medium', label: 'Recommendation / composite score', methodology: 'Unified institutional recommendation engine: Quality 35% (6 fundamental factors) + Valuation 25% (P/E-P/B-yield-PEG vs. sector, blended with margin-of-safety from the sector-appropriate valuation model) + Technical 15% (technical scorecard) + Risk 15% inverted (institutional composite risk score) + Relative positioning 10% (vs. sector peers), renormalized over only the buckets that resolve. The same engine drives every Recommendation tag in this app; see recommendationConfidence and the Valuation tab\'s Recommendation card for the confidence read and any consistency caps applied.' },
  recommendationConfidence: { tier: 'heuristic', confidence: 'Medium', label: 'Recommendation confidence', methodology: 'Blend of data completeness, whether a real intrinsic-value model resolved (DCF or the financial-sector substitute), how many of the 5 institutional risk categories resolved, earnings stability (business-quality factor) and the sector valuation model\'s own confidence band. A stock cannot show Strong Buy without High confidence, and cannot show Buy or better while its own composite risk score is elevated or its own valuation is materially overvalued -- any such cap is disclosed in recommendation.capNote.' },
  fairValue: { tier: 'heuristic', confidence: 'Medium', label: 'Fair value / Target price', methodology: 'In-house P/E and P/B reversion to this watchlist’s own peer average — not analyst consensus or a DCF.' },
  industryPe: { tier: 'calculated', confidence: 'Medium', label: 'Sector/industry P/E', methodology: 'Average P/E across this watchlist’s own companies — there is no market-wide sector database in this app, so this is a watchlist-scoped peer figure, not a true sector benchmark.' },
  relativeStrengthPct: { tier: 'calculated', confidence: 'High', label: 'Relative strength', methodology: 'Stock’s trailing-1y return minus the market benchmark’s trailing-1y return.' },
  supportResistance: { tier: 'heuristic', confidence: 'Low', label: 'Support / resistance', methodology: 'Nearest real level below/above price (DMAs, 52W range) — not literal pivot-point or order-book levels.' },

  beta: { tier: 'calculated', confidence: 'Medium', label: 'Beta', methodology: 'Covariance of weekly stock returns vs. the market benchmark’s weekly returns ÷ benchmark variance, over the trailing ~2 years. N/A for Global watchlists (no defensible single benchmark spans every exchange).' },
  wacc: { tier: 'heuristic', confidence: 'Medium', label: 'WACC', methodology: 'CAPM cost of equity (fixed risk-free-rate and equity-risk-premium assumptions per market — no live rate feed exists) blended with after-tax cost of debt, weighted by market-cap equity and reported-debt weights.' },
  dcfFairValue: { tier: 'heuristic', confidence: 'Medium', label: 'DCF fair value (Bull/Base/Bear)', methodology: 'In-house 2-stage discounted-FCF model over reported free cash flow, discounted at the WACC estimate above; Bull/Base/Bear vary the growth/margin assumption by ±1 historical standard deviation. Unavailable where free cash flow history is missing or non-positive. Not applicable for banks/NBFCs/insurers/asset managers -- see financialSectorValuation.' },
  financialSectorValuation: { tier: 'heuristic', confidence: 'Medium', label: 'Justified P/B fair value (Bull/Base/Bear)', methodology: 'Substitutes for DCF on banks, NBFCs, insurers and asset managers, where a levered-FCF model doesn\'t map to the balance sheet. Justified P/B = (ROE - g) / (Cost of Equity - g) -- algebraically the excess-return (residual income) model expressed as a P/B multiple. Cost of Equity is CAPM (same disclosed risk-free-rate/equity-risk-premium assumptions as the DCF model above); g is the sustainable growth rate (ROE x retention ratio from the reported dividend payout ratio). Fair value = Justified P/B x reported book value per share; Bull/Bear flex ROE by a disclosed ±2pp band.' },
  reverseDcf: { tier: 'calculated', confidence: 'Medium', label: 'Reverse DCF implied growth', methodology: 'Growth rate that reconciles the DCF model’s present value to today’s market cap, solved by binary search — arithmetic on the same disclosed model above, not an independent estimate.' },
  dcfSensitivity: { tier: 'calculated', confidence: 'Medium', label: 'Sensitivity grid', methodology: 'Fair value recomputed across a small WACC × terminal-growth grid — arithmetic on the disclosed DCF model.' },
  valuationConfidenceScore: { tier: 'heuristic', confidence: 'Medium', label: 'Valuation confidence score', methodology: 'In-house blend of input-data completeness and agreement between the DCF and P/E-P/B reversion fair values.' },
  peHistoricalPercentile: { tier: 'calculated', confidence: 'Medium', label: 'Historical P/E percentile', methodology: 'Current P/E ranked against a reconstructed per-fiscal-year P/E series (reported EPS vs. the nearest available weekly close) — an approximation, not an exact FY-end close.' },
  pbHistoricalPercentile: { tier: 'calculated', confidence: 'Medium', label: 'Historical P/B percentile', methodology: 'Current P/B ranked against a reconstructed per-fiscal-year P/B series; book value per share assumes a constant share count across history (splits/buybacks/dilution not modeled).' },
  evEbitdaPercentile: { tier: 'heuristic', confidence: 'Low', label: 'EV/EBITDA percentile', methodology: 'Not available: Enterprise Value itself is unavailable app-wide (no Cash/Net-Debt data source), so a percentile of it would misrepresent an unavailable base metric.' },
  sectorPremiumDiscount: { tier: 'calculated', confidence: 'Medium', label: 'Sector premium/discount', methodology: 'Stock’s P/E vs. the median P/E of same-sector peers within this watchlist — watchlist-scoped, not a market-wide sector.' },
  earningsYield: { tier: 'calculated', confidence: 'High', label: 'Earnings yield', methodology: 'Reported net profit ÷ market capitalization.' },
  fcfYield: { tier: 'calculated', confidence: 'High', label: 'FCF yield', methodology: 'Reported free cash flow ÷ market capitalization.' },

  relativeValuationScore: { tier: 'calculated', confidence: 'Medium', label: 'Relative valuation score', methodology: 'Share of valuation/quality metrics that beat the same-sector watchlist-peer median, weighted.' },
  sectorRank: { tier: 'calculated', confidence: 'Medium', label: 'Sector / watchlist ranking', methodology: 'Rank by ROCE (falling back to ROE) among same-sector watchlist peers, or the full watchlist — a display ranking, not a re-sort of your saved order.' },
  sectorValuationRank: { tier: 'calculated', confidence: 'Medium', label: 'Sector-adjusted valuation rank', methodology: 'Rank within same-sector watchlist peers by premium/discount vs. sector-median P/E-P/B-PEG (cheapest first) — a purely valuation-based rank, distinct from the ROCE/ROE-based sector rank above.' },
  multiFactorPeerScore: { tier: 'heuristic', confidence: 'Medium', label: 'Multi-factor peer score / rank', methodology: 'Disclosed weighted blend (Value 40% / Quality 35% / Growth 25%) of within-sector percentile ranks on inverted P/E-P/B-PEG, ROE-ROCE, and revenue/EPS growth.' },
  valuationDispersion: { tier: 'calculated', confidence: 'Medium', label: 'Valuation dispersion', methodology: 'Mean/median/standard deviation/coefficient of variation of P/E across each sector’s own watchlist peers — flags a tightly bunched vs. widely scattered peer group.' },
  historicalValuationBand: { tier: 'calculated', confidence: 'Medium', label: 'Historical premium/discount band', methodology: 'Min/25th/median/75th/max of this stock’s own reconstructed historical implied P/E (same reconstruction as the historical P/E percentile), and where today’s P/E sits within that range.' },
  sectorNormalizedValuationScore: { tier: 'heuristic', confidence: 'Medium', label: 'Sector-normalized valuation score', methodology: 'Continuous z-score of P/E-P/B-PEG vs. sector-peer mean/standard deviation (cheaper scores higher), mapped through a clamped linear transform to 0-100 — a finer-grained read than the beat/miss-the-median relative valuation score above.' },
  watchlistValuationPercentile: { tier: 'calculated', confidence: 'Medium', label: 'Watchlist valuation percentile', methodology: 'Percentile rank of “cheapness” (inverse sector premium/discount) across the full watchlist.' },
  relativeAttractivenessScore: { tier: 'heuristic', confidence: 'Medium', label: 'Relative attractiveness score', methodology: 'Disclosed average of the relative valuation score, sector-normalized valuation score and multi-factor peer score — one headline relative-value figure blending all three.' },

  adx: { tier: 'calculated', confidence: 'High', label: 'ADX (14)', methodology: 'Wilder’s 14-period Average Directional Index over the trailing 1y daily OHLC.' },
  atr: { tier: 'calculated', confidence: 'High', label: 'ATR (14)', methodology: 'Wilder’s 14-period Average True Range over the trailing 1y daily OHLC.' },
  obv: { tier: 'calculated', confidence: 'High', label: 'On-Balance Volume', methodology: 'Standard cumulative OBV over the trailing 1y daily close/volume.' },
  accDist: { tier: 'calculated', confidence: 'High', label: 'Accumulation/Distribution', methodology: 'Standard cumulative A/D line over the trailing 1y daily OHLCV.' },
  volumeProfile: { tier: 'heuristic', confidence: 'Low', label: 'Volume profile', methodology: 'Daily-close-bucketed volume histogram over the trailing 1y — a proxy for true intraday tick volume profile, which this data source does not expose. "Price vs. point of control" reads whether current price sits above/below/at the highest-volume bucket, a support/resistance implication off real volume concentration.' },
  multiTimeframeTrend: { tier: 'calculated', confidence: 'Medium', label: 'Multi-timeframe trend', methodology: 'Moving-average alignment computed independently on daily, weekly and monthly closes. Confirmation count/strength is how many of the 3 timeframes agree with the dominant direction.' },
  technicalScores: { tier: 'heuristic', confidence: 'Medium', label: 'Trend / Momentum / Volatility / Breakout scores', methodology: 'In-house 0-100 blends of the indicators above — screening scores, not statistical probabilities.' },
  adxInterpretation: { tier: 'calculated', confidence: 'High', label: 'ADX interpretation', methodology: 'Standard Wilder ADX bands: <20 no trend, 20-25 developing, 25-50 strong, >50 very strong — not an in-house threshold.' },
  atrPct: { tier: 'calculated', confidence: 'High', label: 'ATR (normalized to price %)', methodology: 'ATR ÷ price — makes ATR comparable across stocks with very different price levels.' },
  volumeWeightedMomentum: { tier: 'heuristic', confidence: 'Medium', label: 'Volume-weighted momentum', methodology: 'Daily returns over the trailing 20 bars, weighted by each day’s share of total volume — momentum confirmed by participation, not a simple average return.' },
  trendPersistenceScore: { tier: 'calculated', confidence: 'Medium', label: 'Trend persistence score', methodology: 'R² of an ordinary-least-squares line fit through the trailing 50 closes — a real statistic (coefficient of determination); near 100 = a smooth persistent trend, near 0 = choppy price action.' },
  breakoutQualityScore: { tier: 'heuristic', confidence: 'Medium', label: 'Breakout quality score', methodology: 'Like the breakout probability score, but weighted toward volume confirmation and ADX trend strength rather than proximity to resistance alone.' },
  volatilityAdjustedMomentum: { tier: 'heuristic', confidence: 'Medium', label: 'Volatility-adjusted momentum', methodology: 'The momentum score’s deviation from neutral (50), scaled down as ATR% rises — a Sharpe-ratio-style read (momentum per unit of volatility).' },
  relativeStrengthPercentile: { tier: 'calculated', confidence: 'Medium', label: 'Relative strength percentile', methodology: 'Percentile rank of this stock’s relative strength (trailing-1y return vs. benchmark) across this watchlist’s own companies — watchlist-scoped, not a market-wide percentile.' },
  institutionalAccumulationScore: { tier: 'heuristic', confidence: 'Low', label: 'Institutional accumulation score', methodology: 'Blend of OBV/Accumulation-Distribution trend direction, DI+ dominance and up-day volume share — a "smart money" style heuristic, not a real institutional order-flow feed (this app has no such data source).' },
  technicalRegime: { tier: 'heuristic', confidence: 'Medium', label: 'Technical regime', methodology: 'Rule-based qualitative label combining ADX trend strength, multi-timeframe alignment and the volatility score — a screening summary, not a statistical regime-detection model.' },
  technicalSignalConfidence: { tier: 'heuristic', confidence: 'Medium', label: 'Technical signal confidence', methodology: 'Blend of how many core technical indicators resolved (ADX/RSI/MACD/OBV) and multi-timeframe agreement — same "confidence is data completeness + corroboration" pattern as the DCF/recommendation confidence bands.' },

  targetWeightPct: { tier: 'sourced', confidence: 'High', label: 'Target weight %', methodology: 'User-entered allocation target, not derived. Unset holdings split the remaining weight equally; the full vector is normalized to sum to 100%.' },
  portfolioValue: { tier: 'calculated', confidence: 'Medium', label: 'Total portfolio value', methodology: 'An illustrative index (Σ weight × price) since weights are allocation percentages, not disclosed rupee/dollar holdings — not a real brokerage valuation.' },
  diversification: { tier: 'calculated', confidence: 'High', label: 'Diversification / HHI / effective holdings', methodology: 'Herfindahl-Hirschman Index over sector or position weights (Σ share²); effective holdings = 1 ÷ HHI — both real named formulas.' },
  correlationMatrix: { tier: 'calculated', confidence: 'Medium', label: 'Correlation matrix', methodology: 'Pearson correlation of weekly returns over the trailing ~1-2 years of overlapping price history per pair.' },
  portfolioQualityScore: { tier: 'calculated', confidence: 'Medium', label: 'Portfolio quality score', methodology: 'Weight-aggregated average of each holding’s already-computed quality/valuation/technical/risk scores.' },
  scenarioImpact: { tier: 'heuristic', confidence: 'Low', label: 'Scenario impact', methodology: 'Illustrative stress-test: a disclosed multiplier per scenario applied to each stock’s real leverage/interest-coverage/beta/historical-drawdown/sector/earnings-quality characteristics — not a factor model or historical backtest. Currency shock direction/magnitude comes from a static sector-keyword exposure lookup.' },
  cashTargetPct: { tier: 'sourced', confidence: 'High', label: 'Cash allocation target %', methodology: 'User-entered, watchlist-level illustrative cash allocation — invested company weights normalize to sum to (100 − this value) instead of always assuming fully invested.' },
  portfolioBeta: { tier: 'calculated', confidence: 'Medium', label: 'Portfolio beta', methodology: 'Weighted average of each holding’s already-computed beta (covariance of weekly returns vs. its market benchmark).' },
  riskAdjustedReturnScore: { tier: 'calculated', confidence: 'Low', label: 'Risk-adjusted return (proxy Sharpe)', methodology: '(Trailing-1y price return − the disclosed per-market risk-free-rate assumption already used by the DCF/WACC model) ÷ annualized realized volatility. An approximation: trailing 1y price return only, not a full return series or total return including dividends — not a rolling or ex-ante Sharpe ratio.' },
  rollingCorrelation: { tier: 'calculated', confidence: 'Medium', label: 'Rolling correlation / stability', methodology: 'Average pairwise correlation over a recent ~6-month window vs. the full available history. Stability = 100 − the average absolute per-pair difference between the two windows — a heuristic read on whether pairwise relationships have shifted recently, not a significance test.' },
  sectorContribution: { tier: 'calculated', confidence: 'Medium', label: 'Sector contribution', methodology: 'Each sector’s share of portfolio weight and its weight-normalized contribution to the portfolio quality/risk scores — a decomposition of the already-computed portfolio quality/risk figures.' },
  positionRiskContribution: { tier: 'calculated', confidence: 'Medium', label: 'Position (marginal) risk contribution', methodology: 'Standard portfolio-variance decomposition: contribution_i = weight_i × volatility_i × Σ(weight_j × volatility_j × correlation_ij) ÷ portfolio volatility, normalized to % of total. Limited to symbols the correlation matrix itself could resolve.' },
  portfolioAttribution: { tier: 'calculated', confidence: 'Medium', label: 'Portfolio quality / valuation attribution', methodology: 'Weighted-deviation-from-mean attribution (contribution = weight × (holding score − portfolio-weighted average)) — which holdings pull a portfolio-level score up or down.' },
  factorExposure: { tier: 'heuristic', confidence: 'Low', label: 'Factor exposure (Value / Growth / Quality / Momentum / Size)', methodology: 'In-house within-watchlist percentile tilt of an already-computed metric per factor (inverted P/E; revenue/EPS growth; recommendation quality bucket; momentum score; market cap), weight-aggregated to portfolio level. 50 = neutral. Not a commercial risk-factor model (e.g. Barra/Axioma) and not benchmarked against a market-wide factor universe.' },

  financialRisk: { tier: 'calculated', confidence: 'Medium', label: 'Financial risk', methodology: 'Blend of interest coverage, debt trend and working-capital efficiency, all from reported figures.' },
  businessRisk: { tier: 'heuristic', confidence: 'Low', label: 'Business risk', methodology: 'Margin-stability is calculated from reported data; revenue/customer concentration and execution risk have no data source in this app and render as unavailable.' },
  marketRisk: { tier: 'calculated', confidence: 'Medium', label: 'Market risk', methodology: 'Blend of beta, realized volatility and drawdown history, all from real price series, plus a valuation-compression read off the P/E percentile.' },
  sectorRisk: { tier: 'heuristic', confidence: 'Low', label: 'Sector risk (regulatory / commodity / competitive / tech disruption)', methodology: 'Static, keyword-matched sector → qualitative risk tag lookup this project maintains — not a live regulatory or commodity data feed.' },
  governanceRisk: { tier: 'heuristic', confidence: 'Low', label: 'Governance risk', methodology: 'Promoter-holding trend is real; capital allocation is a heuristic blend of ROCE/debt/capex trends; pledge and related-party exposure have no data source and render as unavailable.' },
  compositeRiskScore: { tier: 'heuristic', confidence: 'Medium', label: 'Composite risk score', methodology: 'Weighted blend of the category scores above, renormalized over only the categories that resolve for this stock.' },
  riskTrend: { tier: 'heuristic', confidence: 'Low', label: 'Risk trend', methodology: 'A same-visit directional read off already-computed debt/margin/price trends — this app stores no historical score time series, so this is not a multi-period trend line.' },
  portfolioRiskContribution: { tier: 'calculated', confidence: 'Medium', label: 'Portfolio risk contribution', methodology: 'Holding weight × composite risk score.' },

  // -- Research report (Phase 3d): all derived from analytics already listed
  // above -- these entries only cover the small number of genuinely new
  // presentational concepts the report introduces (data/reporting/
  // researchReport.mjs), not new calculations. --
  investmentHorizon: { tier: 'heuristic', confidence: 'Medium', label: 'Investment horizon', methodology: 'Fixed at 12 months, inherited from the Target Price model\'s own documented methodology (Fair Value grown one year by 5Y EPS CAGR — see fairValue) — not an independently modeled holding period.' },
  idealEntryZone: { tier: 'heuristic', confidence: 'Low', label: 'Ideal entry zone', methodology: 'Illustrative band between the Bear-case and Base-case fair value from the resolved valuation model (DCF or, for financial institutions, the justified-P/B model) — not a technical support level or a recommended limit-order price.' },
  riskRewardSummary: { tier: 'heuristic', confidence: 'Low', label: 'Risk-reward summary', methodology: 'Upside to Target Price vs. downside to the Bear-case fair value, both already-computed percentages — a simple ratio, not a probability-weighted expected-value model.' },
  whyOwnAvoid: { tier: 'heuristic', confidence: 'Medium', label: 'Why own / Why avoid', methodology: 'Generated from the unified recommendation engine\'s own 5 bucket scores (Quality/Valuation/Technical/Risk/Relative positioning) — a bucket scoring ≥60 becomes a "why own" bullet, <40 becomes a "why avoid" bullet, using that engine\'s own driver labels. No new thresholds beyond what the recommendation engine already uses.' },
  technicalCatalyst: { tier: 'heuristic', confidence: 'Low', label: 'Technical catalyst', methodology: 'A single synthesized catalyst row from the technical regime and signal-confidence read, timeline "Ongoing" — no fetched or fabricated event date.' },

  // -- Phase 4 decision layer (data/decision/*.mjs): composition over
  // already-computed analytics/recommendation/risk output — no new
  // calculation, just a new blend and a new persisted run-over-run
  // comparison. Weights, bands and thresholds are fixed constants in
  // data/decision/config.mjs, not empirically calibrated. --
  actionScore: { tier: 'heuristic', confidence: 'Medium', label: 'Portfolio Action Score', methodology: 'Weighted blend of the recommendation engine\'s own Quality/Valuation/Technical/Risk(inverted)/Relative-positioning bucket scores plus a new Portfolio Fit score (weight drift vs. target, sector concentration, correlation with the largest existing holding), renormalized over whichever buckets resolve. Maps to Add aggressively/Add/Hold/Reduce/Exit via fixed score bands — weights and bands live in data/decision/config.mjs, uncalibrated against real outcomes. When fewer than half of the 6 buckets resolve, the label is capped to Hold regardless of the raw score (too little signal coverage for a confident Add/Reduce/Exit call) — disclosed via a capNote in the same tooltip.' },
  portfolioFitScore: { tier: 'heuristic', confidence: 'Low', label: 'Portfolio fit score', methodology: 'In-house read of whether adding to this position improves or worsens portfolio construction — weight drift vs. target, this holding\'s sector concentration, and correlation with the largest existing position, averaged. Feeds the Portfolio Action Score above; not published standalone elsewhere in the app.' },
  portfolioHealthScore: { tier: 'heuristic', confidence: 'Medium', label: 'Portfolio health score', methodology: 'Weighted blend of already-computed portfolio quality, diversification, risk (inverted), technical strength and sector balance scores — weights fixed in data/decision/config.mjs. Trend compares against a run-over-run history now persisted per watchlist (data/cache/watchlistSnapshots/), advanced only on a genuine data refresh, never a cache-only re-render.' },
  alertSeverity: { tier: 'heuristic', confidence: 'Medium', label: 'Alert severity (Critical/High/Medium/Low)', methodology: 'Rule-based severity assigned by how far a valuation/technical/risk/portfolio condition or change exceeds a fixed threshold in data/decision/config.mjs — not a statistical anomaly score. Most alert types now grade across 2-3 tiers by magnitude (e.g. RSI 70 vs. 80, sector concentration 40% vs. 65% vs. 85%) rather than one fixed severity regardless of how extreme the reading is. Standing conditions (e.g. elevated risk) keep firing the same alert id until the condition clears or the alert is acknowledged; crossing events (e.g. a DMA crossover) fire once, off the persisted run-over-run snapshot. An alert continuously firing for 7+ days escalates one severity tier (ALERT_LIFECYCLE.escalateAfterDays); an acknowledged alert that clears and later re-fires is treated as a new occurrence, not suppressed.' },
  changeDetection: { tier: 'heuristic', confidence: 'Medium', label: 'What changed since last refresh', methodology: 'Field-level diff between the persisted run-over-run snapshot (data/cache/watchlistSnapshots/) and the live recommendation/valuation/risk/technical/relative-valuation fields — a company\'s snapshot only advances on its own genuine data refresh, so this reflects "since the last time this company\'s data actually changed," not since the page was last opened.' },
  rebalancingSuggestion: { tier: 'heuristic', confidence: 'Low', label: 'Rebalancing suggestion', methodology: 'Rule-based read of Portfolio Action Score, weight drift vs. target, sector concentration and quality/risk attribution (all already computed) — a suggestion to consider, not an optimizer output or trade instruction.' },

  // -- Phase 5 (data/decision/thesisTracking.mjs, data/news/companyNews.mjs,
  // data/reporting/*): institutional research report + Portfolio Review Pack.
  // Composition over already-computed analytics/decision-layer output — no
  // new fetches, no new underlying calculations. --
  thesisStatus: { tier: 'heuristic', confidence: 'Medium', label: 'Thesis status (Intact/Improving/Weakening/Broken)', methodology: 'In-house classification blending run-over-run deltas already computed by the change-detection layer: recommendation tier movement (dominant weight), composite risk score direction, technical regime/moving-average/MACD direction, and relative-valuation rank movement. A 2+ tier rating downgrade, a fall to Sell, or composite risk crossing into critical territory is a hard "Broken" trigger regardless of the blended score. Weights/thresholds fixed in data/decision/config.mjs\'s THESIS_TRACKING block, uncalibrated against real outcomes (same disclosure as Action Score/alert severity above). Reads "Intact" with no prior snapshot to compare against.' },
  catalystCategory: { tier: 'heuristic', confidence: 'Low', label: 'Catalyst category', methodology: 'Keyword-classified news headline, sorted into one of 7 categories (Earnings/Valuation/Industry/Regulatory/Technical/Management/Capital allocation) by the first matching disclosed pattern — "Technical" is synthesized separately from the technical scorecard, not from news. A category label, not an editorial rating or a confirmed forward-looking event.' },
  catalystSignalStrength: { tier: 'heuristic', confidence: 'Low', label: 'Catalyst signal strength', methodology: 'Deliberately NOT a statistical probability — this app has no confirmed-event calendar. A disclosed heuristic blending the headline\'s already-computed impact tag with its recency (High impact within the last 7 days reads strongest); older or lower-impact headlines read weaker.' },
  positionDiversificationImpact: { tier: 'calculated', confidence: 'High', label: 'Position diversification impact (HHI contribution)', methodology: 'Each holding\'s own share of the portfolio-level Herfindahl-Hirschman Index (share_i² ÷ HHI, as a %) — a decomposition of the already-computed portfolio concentration figure, not an independent calculation.' },

  // -- Phase 6 (data/providers/macroProvider.mjs, data/watchlist/macro.mjs,
  // data/decision/marketRegime.mjs): market and event intelligence layered on
  // top of the existing research platform. Every field here is either a real
  // Yahoo Finance ticker or an explicitly disclosed rule-based classification
  // — nothing is estimated to fill a data-source gap (see the `macroIndicator`
  // entry below for the full list of indicators this app has no source for). --
  macroIndicator: { tier: 'sourced', confidence: 'High', label: 'Macro indicator (USD/INR + 11 more currencies, US 10Y Treasury yield, crude oil, natural gas, gold, India Gold Rate, India VIX, Indian/US/World equity indices)', methodology: 'Latest close/level from Yahoo Finance\'s public chart endpoint for each ticker — the same fetch mechanism and endpoint every equity price in this app already uses. Original 7: INR=X, ^TNX, CL=F, NG=F, GC=F, GOLDBEES.NS, ^INDIAVIX. Macro IA redesign (2026-09-23) added, all live-verified against the chart endpoint before wiring up: Indian Indices — NIFTY 50 (^NSEI), BANKNIFTY (^NSEBANK), NIFTY MIDCAP 50 (^NSEMDCP50), SENSEX (^BSESN); US Macro — S&P 500 (^GSPC), Nasdaq Composite (^IXIC), Dow Jones Industrial Average (^DJI), Russell 2000 (^RUT); World — Nikkei 225 (^N225), Shanghai Composite (000001.SS — the commonly-cited ^SSEC ticker 404s on Yahoo\'s chart endpoint, confirmed live), Hang Seng (^HSI), FTSE 100 (^FTSE), DAX (^GDAXI), CAC 40 (^FCHI). India Gold Rate is the real, unmodified NSE market price of Gold BeES (a physical-gold-backed ETF), not a converted/estimated figure — distinct from the derived commodity conversions, see `commodityInrDerived` below. Change % and 1-year change are that same feed\'s own trailing-window figures. Commodity/currency presentation revision (2026-09-23, same day): Gold/Crude Oil (WTI)/Natural Gas (Henry Hub) now render their raw USD price under a new US Macro → Commodities table (previously shown, unconverted, under an India label — corrected); a new India Macro → Currencies table added 11 more direct `<CCY>INR=X` quotes, each live-verified before being wired in — British Pound (GBPINR=X), Euro (EURINR=X), Swiss Franc (CHFINR=X), Australian Dollar (AUDINR=X), Canadian Dollar (CADINR=X), UAE Dirham (AEDINR=X), Chinese Yuan (CNYINR=X), Singapore Dollar (SGDINR=X), Thai Baht (THBINR=X), Vietnamese Dong (VNDINR=X, shown per 1,000 units — its raw per-unit INR value is ~0.0037, too small to round meaningfully). Russian Ruble was the one currency with no direct ticker (`RUBINR=X` 404s on Yahoo\'s chart endpoint, confirmed live) — see `currencyCrossRateInr` below for how it\'s derived instead. RBI policy repo rate, India 10-Year G-Sec yield, Manufacturing PMI, Services PMI, banking system liquidity, India Crude Oil (Indian Basket), India Crude Oil (MCX) and India Natural Gas (MCX) — 8 distinct rows as of the 2026-09-24 audit (PMI and crude oil/natural gas split into their separately-sourced instruments per that task\'s own explicit instruction) — have no free, unauthenticated, machine-readable, legally-usable programmatic source this app can reach: re-verified live 2026-09-24 (not carried over from the 2026-09-08/09 audits; see macroProvider.mjs\'s UNAVAILABLE_MACRO_INDICATORS comment for the full per-source citation — each entry now also carries its own `source`/`sourceUrl`/`statusNote` fields so the UI\'s Source column and status badge disclose the real authoritative provider, RBI/FBIL/CCIL/S&P Global/PPAC/MCX, and the specific access limitation — "Not Programmatically Available" (a real source exists but only as a browsable page/portal, never an API) or "Licensing Required" (a real source exists but needs a paid subscription or signed license this app does not have) — never a generic "no source" label). data.gov.in was identified this same session as a *possible* future source for some of these (a free, self-serve API key) but deliberately not pursued — CLAUDE.md requires the same explicit user sign-off any new credentialed integration got for MoSPI, not sought this session; see docs/governance/roadmap.md\'s 2026-09-24 entry. All-India Power Demand moved OUT of this list the same audit — see `nppPowerDemand` below. CPI Inflation, Index of Industrial Production and All-India Power Demand are all public/unauthenticated (MoSPI for CPI/IIP, National Power Portal for Power Demand) — see `mospiCpiIndicator`/`mospiIndicator`/`nppPowerDemand` below; all three render in the same India Macro Indicators table, not a separate credential-gated one. Ethanol blending policy and Union defence budget moved out of the Future Integration list 2026-09-09 — see `periodicMacroIndicator` below. World Asia/Europe rows additionally disclose a Country column (2026-09-23, same-day follow-on alongside a sticky-header fix for these two tables) — Japan/China/Hong Kong for Asia, United Kingdom/Germany/France for Europe — the objectively verifiable home market of each named index, curated alongside its ticker/label/category in macroProvider.mjs\'s WORLD_INDEX_INDICATORS, not fetched or estimated (same static-metadata basis as label/category/unit, which carry no separate registry entry either).' },
  commodityInrDerived: { tier: 'calculated', confidence: 'High', label: 'Derived commodity price in INR (Gold ₹/10g, Crude Oil (WTI) ₹/bbl, Natural Gas (Henry Hub) ₹/MMBtu)', methodology: 'Pure arithmetic unit conversion over two already-fetched Yahoo tickers, NOT an independently sourced Indian price: US commodity price (GC=F/CL=F/NG=F, see `macroIndicator`) × USD/INR (INR=X, the one canonical FX input reused by reference, never refetched, for every conversion on this page). Gold additionally applies × (10 ÷ 31.1034768), the standard troy-ounce-to-gram conversion factor (`goldInrPer10g()`); Crude Oil and Natural Gas need only the currency conversion, no unit-of-measure step (`usdToInr()`) — both pure, zero-I/O functions in data/providers/macroProvider.mjs, applied in data/watchlist/macro.mjs\'s toDerivedIndicator(). Distinct from the existing `goldIndia`-tagged India Gold Rate (Gold BeES ETF, a real NSE-traded market price, carrying no `calculated` flag) — shown alongside it in the Macro workspace\'s India Macro → Commodities tab with a tooltip disclosing each formula, styled with this app\'s existing fetched-vs-derived visual convention. The raw USD source price for all three remains available, unconverted, under the US Macro → Commodities tab (`macroIndicator` above) — never shown a second time under an India label. Status is Live only when both underlying tickers resolved Live this cycle, Delayed if either fell back to a stale cache, and Unavailable (value left blank, never fabricated) if either input never resolved. Formerly registered under the narrower key `goldInrPer10g` (gold only) before this same conversion pattern was extended to Crude Oil/Natural Gas, 2026-09-23.' },
  currencyCrossRateInr: { tier: 'calculated', confidence: 'High', label: 'Russian Ruble (RUB) — derived via USD cross-rate (₹)', methodology: 'RUB is the one currency of the 12 shown in India Macro → Currencies with no direct Yahoo `RUBINR=X` quote (confirmed live, HTTP 404 on the chart endpoint). Derived instead from two already-fetched USD legs — USD/INR (INR=X, the same canonical FX input every other India Macro derivation reuses) and USD/RUB (RUB=X, fetched solely as a cross-rate input and never itself rendered as its own row) — via crossRateInr(usdInr, usdRub) = usdInr ÷ usdRub, a pure, zero-I/O function in data/providers/macroProvider.mjs. Every other currency in that table is a direct fetched quote, not a cross-rate; RUB\'s row carries `calculated: true` and the same fetched-vs-derived visual styling as `commodityInrDerived` above. Status is Live only when both legs resolved Live this cycle, Unavailable (value left blank, never fabricated) if either never resolved.' },
  mospiCpiIndicator: { tier: 'sourced', confidence: 'Medium', label: 'CPI Inflation — Consumer Food Price Index (MoSPI eSankhyiki, public)', methodology: 'Official Government of India statistics from MoSPI\'s eSankhyiki API platform (api.mospi.gov.in/api/cpi/getCPIIndex), fetched with ZERO credentials — no signup, login, password or access token (2026-09-08 CPI-without-credentials task; verified live). MoSPI\'s own CPI API User Manual documents this as intentional platform behavior, not a workaround: "without access token the APIs will fetch only the first 10 records." Because every query filter (Year/Month/Group_code/Sector/State_code) is silently ignored by MoSPI\'s server for unauthenticated callers (also live-confirmed), this app cannot select the headline "General"/all-India-all-groups CPI figure the way a credentialed call could — it searches the fixed ~10-record unfiltered slice MoSPI returns for the Consumer Food Price Index ("Consumer Food Price" group, an "...-Overall" subgroup), the one complete, officially-labeled series consistently present there. This is deliberately NOT the same figure as headline CPI inflation — the label says so throughout this app. The Index value and the Year-on-Year inflation % shown are both read directly off MoSPI\'s own response fields (`index`, `inflation`) — never recomputed, per MoSPI\'s own directly-supplied inflation field taking priority over an independent calculation this app cannot verify without a 12-months-prior data point it cannot select. The `sector` actually returned (observed: Rural) is disclosed alongside the reading rather than assumed to be an All-India-Combined figure. Confidence is Medium rather than High because of that sector/series-selection limitation and because the exact unauthenticated response shape was confirmed only during this task\'s own live verification pass, not against MoSPI\'s own published schema (their manuals show request parameters, not a response schema). A live TLS misconfiguration on MoSPI\'s own server (`ERR_SSL_UNSAFE_LEGACY_RENEGOTIATION_DISABLED` under Node\'s default settings) required one narrow, user-approved exception to reach it at all — see data/integrations/mospiClient.mjs\'s fetchCpiPublic() and docs/authoritative/system.md §3.10 for the full disclosure; certificate verification itself is never weakened, only the TLS renegotiation policy, and only for this one call.' },
  mospiIndicator: { tier: 'sourced', confidence: 'Medium', label: 'Index of Industrial Production — General Index (MoSPI eSankhyiki, public)', methodology: 'Official Government of India statistics from MoSPI\'s eSankhyiki API platform (api.mospi.gov.in/api/iip/getIIPMonthly, endpoint path corroborated by the official nso-india GitHub organization\'s open-source client — no dedicated IIP manual exists the way CPI/WPI each have one), fetched with ZERO credentials — no signup, login, password or access token. This app\'s original 2026-09-08 build assumed IIP needed a token like the rest of that integration; a completely independent 2026-09-09 investigation (explicitly instructed not to assume IIP behaves like CPI) live-tested IIP\'s own endpoint from scratch and found the identical platform behavior CPI already used: a fixed, unfiltered ~10-record anonymous slice, every query filter silently ignored, real current data (not an empty array or "No Data Found"). That anonymous slice consistently placed the headline General/Overall IIP record (type "General", category "General") first — the officially-preferred series this app displays, never a sub-series (Manufacturing/Mining/Electricity) substituted in its place. The Index value and the Year-on-Year growth % shown are both read directly off MoSPI\'s own response fields (`index`, `growth_rate`) — never recomputed; the "growth_rate" field is treated as Year-on-Year per MoSPI\'s standard published IIP press-release convention (no manual language to cite for IIP specifically, unlike CPI\'s documented "inflation" field). Confidence is Medium rather than High for the same class of reason as CPI: this app has no published response schema to confirm against, only its own live verification pass. The same live-confirmed TLS misconfiguration on MoSPI\'s server required the same narrow, already-approved legacy-renegotiation exception, independently re-verified for this endpoint rather than assumed — see data/integrations/mospiClient.mjs\'s fetchIipPublic() and docs/authoritative/system.md §3.10. No daily change % or moving averages are shown — a monthly government index is a period-over-period reading, not a priced instrument (see macroTrend below\'s own scope note).' },
  nppPowerDemand: { tier: 'sourced', confidence: 'High', label: 'All-India Power Demand (Demand Met, NPP)', methodology: '2026-09-24 Future Integration audit ("implement the remaining India Macro indicators from their authoritative non-MoSPI sources" task): National Power Portal (NPP, npp.gov.in — a Government of India platform, Ministry of Power, operated by the National Informatics Centre) serves a real, public, unauthenticated JSON endpoint backing its own live dashboard (GET npp.gov.in/dashBoard/demandmet1chartdata?date=YYYY-MM-DD), live-verified this session with a bare header-less GET — no API key, no cookies, no session. This is a different mechanism from every one previously tested for this indicator (CEA\'s documented but non-functional psp_peak.php/psp_energy.php API, Grid-India/POSOCO\'s PDF-only PSP reports, NPP\'s own separate NPDMS API restricted to registered government organizations — see macroProvider.mjs\'s UNAVAILABLE_MACRO_INDICATORS comment for that history) and was not tested in either the 2026-09-08 or 2026-09-09 audit. The latest "DEMAND MET" reading (MW) and its own real observation timestamp are read directly off NPP\'s response — data/providers/nppProvider.mjs\'s pickLatestDemandMet(), unit-tested against synthetic fixtures (test/nppPowerDemand.test.mjs), picks the maximum `updated_on` row rather than assuming array order. No changePct/trend/DMA — a ~4-minute intraday reading has no established daily-close series in this app to compute a moving average from, same disclosed limitation as CPI/IIP\'s monthly index. Falls back to the prior day\'s last reading (status Delayed) only for the narrow edge case of very early morning before the first same-day sample exists; a fetch failure with no cache renders Unavailable, never a fabricated value.' },
  mospiCredential: { tier: 'calculated', confidence: 'High', label: 'MoSPI credentialed-dataset status (Not Configured / Credentials Required / Configured / Connected / Authentication Failed / Token Expired / Provider Unavailable)', methodology: 'Describes the credentialed MoSPI path only — currently unpopulated (2026-09-09: IIP, the last dataset gated by it, was independently investigated and proven public, joining CPI; see mospiCpiIndicator/mospiIndicator above, neither ever gated by any of the states below). Kept as working infrastructure for any future MoSPI dataset that genuinely requires a credential. Not Configured = no token has ever been obtained. Configured = a token is stored but has not yet been confirmed against a real data fetch. Connected = the last data fetch using the stored token succeeded. Authentication Failed = MoSPI rejected the credential (bad password, or a 401/403 on a data call). Token Expired = the stored token is past its documented 15-minute lifetime with nothing re-issued. Provider Unavailable = a non-authentication network/upstream error. The MoSPI account password is never stored by this app in any state — see data/integrations/credentialStore.mjs\'s own top comment for the local-plaintext-file design this single-user, local-only tool uses instead of a secrets vault.' },
  macroDataQuality: { tier: 'calculated', confidence: 'High', label: 'Macro Data Quality status (Live / Delayed / Unavailable / Periodic / Future Integration)', methodology: 'Live = fetched within the last 30 minutes (CPI/IIP: within their own 6-hour cache window — both public, neither needs a prior connection). Delayed = a fresh fetch failed but a previously cached reading exists and is shown instead. Unavailable = no cached reading exists and the fetch failed. Periodic = a real, officially-sourced but annual/event-cadence reading with no live feed to refresh from (added 2026-09-09 — see periodicMacroIndicator below); deliberately kept out of the Live bucket, which the panel documents as "fetched within the last 30 minutes." Future Integration = this app has no legitimate programmatic way to fetch this indicator today (see macroIndicator above) — a fixed disclosure, not a live check; each row\'s own status is the specific reason ("Not Programmatically Available" or "Licensing Required" since the 2026-09-24 audit, previously one undifferentiated "Future Integration" label), and its Source column names the real authoritative provider even though this app cannot reach it. No "Credentials Required" bucket exists as of 2026-09-09 — no macro indicator in this app is gated on a MoSPI credential any more (see mospiCredential above).' },
  periodicMacroIndicator: { tier: 'sourced', confidence: 'Medium', label: 'Periodic/Policy indicator (Union Defence Budget, Ethanol Blending Rate)', methodology: '2026-09-09 re-verification task ("re-audit every deferred India Macro indicator, don\'t trust the prior audit as final"): both figures were found to have no live API but a clear, current, officially-published value, and are shown as a dated one-time reading rather than kept in the "Future Integration" bucket or invented as a fake daily feed. Union Defence Budget: ₹7,84,678 crore total allocation for FY2026-27, sourced from the Union Budget 2026-27 Demand for Grants (Ministry of Finance, presented 2026-02-01) and cross-checked against PRS Legislative Research\'s own published Demand for Grants analysis (a well-established independent, non-partisan Indian parliamentary research body, not a primary government source itself). Ethanol Blending Rate: 20% petrol-blending achieved in ESY 2025-26 (five years ahead of the original 2030 target), sourced directly from a PIB (Press Information Bureau, Ministry of Petroleum & Natural Gas) official backgrounder dated 2026-07-05. Neither value is fetched automatically — both are manually curated static entries in data/providers/macroProvider.mjs\'s PERIODIC_MACRO_INDICATORS, refreshed by hand at the next official publication (the next Union Budget; the next PIB ethanol-blending update), and carry no changePct/trend/DMA fields (an annual/event-cadence figure has no daily series to compute one from). Confidence is Medium rather than High because — unlike this app\'s fetched indicators — a stale manual entry would not self-correct or flag itself; the as-of date is always shown so staleness is at least visible.' },
  macroTrend: { tier: 'calculated', confidence: 'High', label: 'Macro indicator trend (Trend / 20-50-100-200 DMA / DMA alignment)', methodology: 'Same calculation this app already uses for every equity (see `movingAverages`/technical Trend table): simple moving averages of the real trailing daily-close history Yahoo Finance\'s chart endpoint returns for each macro ticker, reused verbatim from yahooQuoteProvider.mjs\'s fetchQuote() — not a second technical-analysis engine. A period renders blank until enough trading days exist (never estimated). Trend is Uptrend when price > 50 DMA > 200 DMA, Downtrend when price < 50 DMA < 200 DMA, otherwise Sideways/Mixed — the same rule the equity Trend table\'s own `trend` column already uses. DMA alignment is how many of the 4 DMAs the current price sits above. Only shown for indicators with a real fetched price series (the Macro workspace\'s India Macro/US Macro/World tables); Future Integration indicators have no price series to compute a trend from, and the derived Gold ₹/10g row (see `goldInrPer10g`) shows N/A here since it has no independent price history of its own.' },
  marketRegime: { tier: 'heuristic', confidence: 'Low', label: 'Market regime (Risk-on / Risk-off / liquidity bias)', methodology: 'Rule-based read combining India VIX level, the Nifty 50 benchmark\'s own trend (already computed for Relative Strength elsewhere in this app, reused rather than refetched), and the direction of the US 10-Year Treasury yield — the same disclosed rule-based-classification pattern the single-stock technical regime already uses (see `technicalRegime`), applied at market level. Not a statistical regime-detection model; confidence is capped at Medium and reads Low whenever fewer than 3 of its inputs resolve.' },
  sectorIntelligence: { tier: 'calculated', confidence: 'Medium', label: 'Sector Intelligence rollup', methodology: 'Simple (unweighted) average of already-computed per-company fields (recommendation composite score, valuation bucket score, technical trend-strength score, institutional risk composite score, relative strength vs. benchmark, 5-year EPS CAGR), grouped by each company\'s own sector across every watchlist you\'ve saved — cache-only, no new fetch, no new per-company calculation. Regulatory/commodity sensitivity reuse the existing static sector-risk lookup table (see `sectorRisk`). Coverage is limited to companies you have actually added to a watchlist; there is no market-wide sector database in this app (see docs/governance/roadmap.md TD-10), so a sector with nothing added anywhere simply does not appear.' },
  exposureMatrix: { tier: 'heuristic', confidence: 'Low', label: 'Portfolio Exposure Matrix (interest-rate / currency / commodity / regulatory / economic-cycle sensitivity)', methodology: 'Each company is tagged by its own sector against 4 static, disclosed keyword-matched sensitivity lookup tables this project maintains, not a live regulatory/rates/FX data feed — analyst-style judgment calls, same class of limitation as `sectorRisk`. Interest-rate and economic-cycle sensitivity are new lookup tables (data/analytics/exposureRules.mjs); regulatory and commodity sensitivity reuse the existing sector-risk lookup (`sectorRisk`) directly rather than duplicating it; currency sensitivity reuses the existing scenario-analysis currency-exposure lookup (see `scenarioImpact`). The portfolio-level rollup is a weight-aggregated average using each holding\'s already-resolved illustrative target weight — same weight vector every other portfolio aggregate in this app uses, not a real brokerage holding.' },
  earningsIntelligence: { tier: 'calculated', confidence: 'Medium', label: 'Earnings Intelligence (quarterly revenue / net profit / operating margin deltas)', methodology: 'Real quarter-over-quarter and year-over-year % change (or, for operating margin, a percentage-point delta) computed from Screener.in\'s own scraped quarterly results — a company\'s own reported figures, arithmetic only, no estimate. "Deviation vs. trailing average" compares the latest quarter to that company\'s own trailing 4-quarter average — deliberately not a beat/miss vs. analyst consensus, since this app has no consensus-estimate data source. Next earnings date, days remaining, expected impact, historical earnings reaction, guidance changes, management commentary and estimate-revision signals have no data source and render an explicit "Future Integration" status rather than an invented date or estimate — see the Dashboard\'s Earnings & Events sub-tab.' },
  eventCalendar: { tier: 'sourced', confidence: 'Medium', label: 'Portfolio Event Calendar', methodology: 'Every already-fetched, dated company news item (Google News RSS, same source and classification as the News & catalysts panel) across the watchlist, sorted newest-first — a real published date per item, not an estimate. Earnings dates, dividend ex-dates, buybacks and regulatory/policy events have no dated source in this app (Screener exposes only a trailing annual dividend payout %, not a schedule) and are not included rather than fabricated.' },
  newsSentiment: { tier: 'heuristic', confidence: 'Low', label: 'News sentiment (Positive / Negative / Neutral / Uncertain)', methodology: 'Keyword-based read over the headline text (two disclosed word lists, same style/location as the existing impact classifier) — not an NLP sentiment model and not an editorial rating. A headline matching both lists (a genuinely mixed signal) reads Uncertain rather than an invented 5th category.' },
  affectedThesisDriver: { tier: 'heuristic', confidence: 'Low', label: 'Affected thesis driver', methodology: 'A coarse, disclosed many-to-one mapping from the existing 7-category catalyst taxonomy to the per-company report\'s own investment-thesis buckets (Business quality / Growth drivers / Competitive position / Valuation opportunity / Key risks — see `whyOwnAvoid`) — a topical association, not a causal claim that this specific headline moved that bucket\'s score. The actual thesis-change read is `thesisStatus`, computed independently from run-over-run score deltas.' },

  // -- Phase 7 Stage 1 (data/quant/factorEngine.mjs): the institutional
  // quantitative factor framework. Every raw sub-metric is read off analytics
  // already computed and tagged above (pe, roe, revenueCagr3y, momentumScore,
  // beta, marketCap, etc.) — this module performs no new fetch and no
  // independent recalculation of any raw figure, only normalization
  // (percentile ranking) and weighted aggregation. --
  quantFactorScore: { tier: 'heuristic', confidence: 'Medium', label: 'Quantitative Factor Score', methodology: 'Institutional 6-factor framework (Value/Quality/Growth/Momentum/Risk/Size). Each named sub-metric (see quantFactorMetric below) is normalized to a 0-100 sector-relative percentile within this watchlist (falling back to watchlist-wide below 4 sector peers, then to explicit "insufficient data" below 3 peers at any scope — there is no market-wide peer database in this app, the same constraint already disclosed on relativeValuation/factorExposure). A category score is the average of its resolved sub-metrics; the Factor Score is a weighted blend of the 6 category scores (weights in data/quant/config.mjs, uncalibrated — same TD-11-class disclosure as every other heuristic weighting in this app), renormalized over resolved categories, and withheld when fewer than half resolve. This is a distinct, more granular capability from the existing portfolio-level `factorExposure` tilt above — not a replacement or a duplicate of it — and it does NOT replace or override the Portfolio Action Score or the unified recommendation engine, which remain this app\'s primary decision-layer signals; a conflicting read between them is surfaced, not averaged away.' },
  quantFactorMetric: { tier: 'calculated', confidence: 'Medium', label: 'Factor sub-metric (raw value, normalized score, percentile, direction)', methodology: 'A single named input to the Factor Score above (e.g. P/E, ROE, revenue CAGR, price momentum, beta, market cap) — the raw value is read directly off this app\'s already-computed analytics, never recomputed. Normalized score = percentile rank of the raw value against the chosen peer universe (sector-first, watchlist fallback), inverted for "lower is better" metrics (e.g. P/E, beta, volatility, composite risk) so a higher normalized score always means more attractive. Metrics with no data source in this app (EV/EBITDA, EBITDA growth, multi-year FCF growth) render an explicit "unavailable" status rather than an estimate.' },

  // -- Phase 7 Stage 2 (data/quant/performanceEngine.mjs): benchmark-relative
  // return, CAGR and risk-adjusted performance. Beta/volatility/max-drawdown
  // magnitudes are reused verbatim from the figures already tagged above
  // (beta, and the risk-category inputs behind marketRisk) — this entry
  // covers only the genuinely new capabilities this stage adds. --
  benchmarkPerformance: { tier: 'calculated', confidence: 'Medium', label: 'Benchmark & Performance (period returns, CAGR, risk-adjusted return)', methodology: 'Benchmark = NIFTY 50 (India) / S&P 500 (US) via the same per-market benchmark bundle already fetched once per market for Relative Strength/beta — "N/A — benchmark unavailable" for markets with no defensible single index, never a substituted benchmark. Period returns (1M/3M/6M/3Y/5Y) are price returns (dividends not included) computed from the weekly 5-year price history series already used for beta/volatility/drawdown, tolerance-matched within ±10 calendar days of the exact lookback target — a period renders "insufficient history" rather than an extrapolated figure when the series doesn\'t reach back far enough. 1Y reuses the existing daily-quote-derived oneYearReturnPct (the same figure already surfaced as Relative Strength) rather than a second weekly-series-derived 1Y figure. CAGR (3Y/5Y only) uses the actual elapsed time between the located observations, not an assumed exact year count. Excess return = stock/portfolio return − benchmark return over the same period. Max drawdown adds peak/trough/recovery dates (or an explicit "not yet recovered") on top of the existing maxDrawdownPct magnitude — no recovery date is fabricated. The Sharpe-like figure is this app\'s existing proxy Sharpe (riskAdjustedReturnScore) reused as-is; the Sortino-like figure is new — (trailing-1y return − the same disclosed per-market risk-free-rate assumption) ÷ annualized downside deviation (weekly returns below 0%, same weekly×√52 annualization as realized volatility). Neither is a conventional-methodology Sharpe/Sortino ratio (both need a full return series and, ideally, dividend-inclusive total return, which this app\'s data sources don\'t provide) — labeled "-like"/proxy throughout, never the official name. Portfolio-level figures weight-aggregate the per-holding figures using the same illustrative target-weight vector every other portfolio aggregate in this app uses; portfolio volatility and beta reuse the already-computed real portfolio-level figures (the same correlation-aware variance decomposition positionRiskContribution uses, and the existing portfolioBeta), not a correlation-blind average — portfolio max drawdown has no equivalent real portfolio-level primitive in this app and is disclosed as a diversification-blind weighted average of each holding\'s own drawdown, not a synthetic portfolio-index drawdown. Holdings in more than one market are each compared to their own market benchmark; the portfolio-level benchmark figure is the weight-aggregated result across those, not a single blended index.' },

  // -- Institutional research foundation upgrade (data/scoring/qualityAttractiveness.mjs,
  // researchQuality.mjs, data/analytics/forwardFramework.mjs, data/decision/
  // thesisTracking.mjs's thesisBreakers, data/metadata/evidenceHierarchy.mjs):
  // additive analytical lenses over already-computed fields -- none of these
  // touch or override the primary recommendation.rating/compositeScore. --
  companyQualityScore: { tier: 'heuristic', confidence: 'Medium', label: 'Company Quality', methodology: 'Weighted average of the business/financial-strength/profitability/growth/cash-flow/balance-sheet/management/industry-position factors (data/scoring/factors.mjs), renormalized over whichever resolve. Deliberately excludes valuation, risk-profile, technical and momentum factors — measures the underlying business independent of today\'s stock price. Additive alongside, never a replacement for, the primary recommendation\'s Quality bucket (a differently-scoped 6-factor subset feeding the blended rating).' },
  stockAttractivenessScore: { tier: 'heuristic', confidence: 'Medium', label: 'Stock Attractiveness', methodology: 'Weighted average of the valuation/risk-profile/technical-trend/momentum-volume factors (data/scoring/factors.mjs), renormalized over whichever resolve — measures whether the current price/market setup is attractive, independent of Company Quality above.' },
  fundamentalView: { tier: 'heuristic', confidence: 'Medium', label: 'Fundamental View', methodology: 'Re-averages the unified recommendation engine\'s own Quality/Valuation/Risk bucket scores (excluding Technical), renormalized over whichever resolve — Positive/Neutral/Negative. Distinct from Market View below; neither replaces the primary blended rating.' },
  marketView: { tier: 'heuristic', confidence: 'Medium', label: 'Market View', methodology: 'The recommendation engine\'s own Technical bucket score plus the technical regime label — Favorable/Neutral/Unfavorable. A weak Market View is never folded into Company Quality or the Fundamental View.' },
  actionGuidance: { tier: 'heuristic', confidence: 'Low', label: 'Action guidance (Fundamental × Market combined read)', methodology: 'A small disclosed lookup table combining Fundamental View and Market View into one guidance sentence (e.g. "Fundamentally attractive but technically weak — accumulate on weakness") — never a third rating, and never lets a Market View reading change Company Quality or the primary recommendation.' },
  peerTier: { tier: 'calculated', confidence: 'Medium', label: 'Peer tier (Direct / Sector)', methodology: 'Direct = shares this stock\'s exact `industry` classification within the watchlist; Sector = shares only the broader `sector` tag. Both remain watchlist-scoped — there is no market-wide peer database in this app (docs/governance/roadmap.md TD-10).' },
  peerCompleteness: { tier: 'calculated', confidence: 'High', label: 'Peer completeness (Strong / Adequate / Weak / Unavailable)', methodology: 'Strong = 6+ same-sector watchlist peers, Adequate = 3–5, Weak = 1–2, Unavailable = 0 (self excluded from the count). Below 3 peers, relativeValuationScore/sectorNormalizedValuationScore/multiFactorPeerScore render null with a disclosed reason rather than a misleading self-comparison artifact — see relativeValuation.mjs.' },
  researchQuality: { tier: 'heuristic', confidence: 'Medium', label: 'Research Quality Gates', methodology: 'Five disclosed gates over already-computed signals: Data completeness (fundamentals field coverage), Valuation completeness (did a real intrinsic-value model resolve), Peer completeness (see peerCompleteness above), Forecast confidence (fixed "not applicable" until a forward-estimate model exists — see forwardFramework), Evidence quality (a coarse blend of recommendation-bucket coverage, valuation-model resolution and data completeness). Confidence is reported as a first-class, separate-from-score output — see recommendation.confidence, which this gate\'s peer-completeness read now also feeds.' },
  forwardFramework: { tier: 'heuristic', confidence: 'Low', label: 'Forward Estimates / Management Credibility / Segment Economics / Capacity-Utilization (foundation contracts)', methodology: 'Schema-only foundation for four concepts this app has no data source for yet: forward estimates (management guidance vs. system estimate vs. actual), management execution/credibility tracking, segment-level economics, and capacity/utilization economics. Each renders an explicit "available: false" with a disclosed reason rather than any fabricated figure — see data/analytics/forwardFramework.mjs. A future data-source integration fills in the named schema fields; nothing here is computed today.' },
  thesisBreakers: { tier: 'heuristic', confidence: 'Medium', label: 'Thesis breakers', methodology: 'A structured, named list of the conditions that would invalidate this company\'s investment thesis — the same 3 hard "Broken" triggers thesisStatus already uses (2+ tier rating downgrade, a fall to Sell, composite risk reaching critical territory), plus 2 additional point-in-time conditions backed by already-computed data (promoter holding declining materially, ROCE falling below the modeled cost of capital). Each carries a condition/status (Active/Watch/Clear/Unavailable)/current reading — status Active does not by itself imply the thesis is Broken (see thesisStatus for the blended classification); this is the transparent checklist behind it, not a duplicate scoring rule.' },
  evidenceHierarchy: { tier: 'heuristic', confidence: 'High', label: 'Evidence hierarchy (A–F)', methodology: 'A–F provenance classification layered on top of (never replacing) the existing Sourced/Calculated/Heuristic tier: A = audited filing/exchange/regulatory, B = management guidance/investor presentation, C = high-quality independent research, D = reputable financial/news source, E = derived calculation, F = system heuristic/estimation. Every metric defaults to a tier-derived evidence classification (sourced→A, calculated→E, heuristic→F, news-sourced items→D) — see data/metadata/evidenceHierarchy.mjs. No B or C source exists in this app today; that gap is disclosed, not filled with an invented mapping.' }
};

import { defaultEvidenceTier, evidenceLabel } from './evidenceHierarchy.mjs';

// Metrics whose `sourced` tier is a news headline (Google News RSS), not a
// filing/exchange figure -- these default to evidence tier D instead of A.
// Every other `sourced` entry above is a reported financial/price figure.
const NEWS_SOURCED_KEYS = new Set(['eventCalendar']);

// Additive evidence-hierarchy (A-F) layer over the existing tier/confidence/
// label/methodology contract -- see data/metadata/evidenceHierarchy.mjs.
// Computed once here rather than hand-annotating all ~90 registry entries:
// every entry's evidence tier is a disclosed *default* derived from its
// existing tier, with the one real exception (news-sourced items) handled
// via NEWS_SOURCED_KEYS above. No entry is upgraded to B or C -- no
// management-guidance or independent-research source exists in this app
// today (see data/analytics/forwardFramework.mjs).
function withEvidenceTier(key, entry) {
  const evidenceTier = defaultEvidenceTier(entry.tier, { isNews: NEWS_SOURCED_KEYS.has(key) });
  return { ...entry, evidenceTier, evidenceLabel: evidenceLabel(evidenceTier) };
}

export function metricMeta() {
  return Object.fromEntries(Object.entries(registry).map(([key, entry]) => [key, withEvidenceTier(key, entry)]));
}
